'use strict';
const studies=window.GRIFFIN_TOPICAL.studies;
const query=document.getElementById('query'),teacher=document.getElementById('teacher'),topic=document.getElementById('topic'),batch=document.getElementById('batch');
for(const label of [...new Set(studies.map(s=>s.topic))].sort()){const o=document.createElement('option');o.value=o.textContent=label;topic.append(o)}
function selectStudies(q='',pastor='',subject='',selectedBatch=''){q=q.trim().toLowerCase();return studies.filter(s=>(!pastor||(pastor==='pending'?!s.teacher:s.teacher===pastor))&&(!subject||s.topic===subject)&&(!selectedBatch||String(s.batch)===selectedBatch)&&(!q||[s.title,s.published_title,s.teacher,s.topic].join(' ').toLowerCase().includes(q)))}
function render(){const rows=selectStudies(query.value,teacher.value,topic.value,batch.value),container=document.getElementById('questions');container.replaceChildren();for(const s of rows){const card=document.createElement('article'),tag=document.createElement('p'),heading=document.createElement('h2'),by=document.createElement('p'),watch=document.createElement('a'),status=document.createElement('p'),details=document.createElement('details'),summary=document.createElement('summary'),original=document.createElement('p'),evidence=document.createElement('a');card.id=s.id;tag.className='eyebrow';tag.textContent=s.topic;heading.textContent=s.title;by.textContent=s.teacher?'Pastor '+s.teacher+' · archive attribution':'Teacher confirmation pending · discovered candidate';watch.textContent='▶ Watch study on YouTube';watch.href=s.url;watch.target='_blank';watch.rel='noopener noreferrer';watch.className='watch';status.textContent='Transcript: to be collected';summary.textContent='Source and attribution';original.textContent=s.published_title+' · '+s.channel+'. Speaker confirmation and full content review are pending.';evidence.textContent=s.teacher?'Teacher attribution source':'Discovery source (not speaker proof)' ;evidence.href=s.teacher_evidence_url;evidence.target='_blank';evidence.rel='noopener noreferrer';details.append(summary,original,evidence);card.append(tag,heading,by,watch,status,details);container.append(card)}document.getElementById('results-count').textContent=rows.length+' of '+studies.length+' video links shown · Batches 001–003';document.getElementById('empty').hidden=rows.length>0}
query.addEventListener('input',render);teacher.addEventListener('change',render);topic.addEventListener('change',render);batch.addEventListener('change',render);document.getElementById('filters').addEventListener('reset',()=>{query.value='';teacher.value='';topic.value='';batch.value='';render()});render();
